"""Legacy-compatible Meridian CRM permission check."""

from typing import Any


def can(
    user: dict,
    action: str,
    object: str,
    record: dict,
    role_rows: list[dict],
) -> bool:
    """Return whether the user may perform an action on a record.

    Permission rows are evaluated in their supplied order. A missing matching
    row denies access. ADMIN bypasses scope only and must still have a matching
    role row.
    """
    role_id = user.get("ROLE_ID", "")
    user_id = user.get("USR_ID", "")
    user_team = user.get("TEAM_CD", "")

    # DELETE is permitted only for records that are not already soft-deleted.
    # A blank or missing CHAR(1) boolean has the legacy value N.
    if action == "DELETE":
        delete_flag = record.get("DEL_FLG", "")
        if delete_flag == "":
            delete_flag = "N"
        if delete_flag != "N":
            return False

    for row in role_rows:
        if (
            row.get("role_id", "") != role_id
            or row.get("object", "") != object
            or row.get("action", "") != action
        ):
            continue

        if role_id == "ADMIN":
            return True

        scope = row.get("scope", "")
        if scope == "ALL":
            return True
        if scope == "TEAM":
            return user_team == record.get("TEAM_CD", "")
        if scope == "OWN":
            return user_id == record.get("OWNER_UID", "")
        return False

    return False
